using AcxiomCRM.Web.Data;using AcxiomCRM.Web.Models;using AcxiomCRM.Web.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Web.Controllers;
[Authorize]public class FollowUpsController:Controller{readonly ApplicationDbContext db;readonly UserManager<ApplicationUser> um;readonly AuditService audit;public FollowUpsController(ApplicationDbContext d,UserManager<ApplicationUser> u,AuditService a){db=d;um=u;audit=a;}string U=>um.GetUserId(User)!;bool Priv=>User.IsInRole("Admin")||User.IsInRole("Manager");
public async Task<IActionResult>Index(){var x=db.FollowUps.Include(f=>f.Customer).Include(f=>f.Opportunity).Include(f=>f.AssignedTo).AsQueryable();if(!Priv)x=x.Where(f=>f.AssignedToId==U);return View(await x.OrderBy(f=>f.FollowUpDate).ToListAsync());}
public IActionResult Create()=>View(new FollowUpVm());
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(FollowUpVm vm){if(vm.FollowUpDate.Date<DateTime.UtcNow.Date)ModelState.AddModelError("FollowUpDate","Follow-up date cannot be earlier than today.");if(vm.CustomerId==null&&vm.LeadId==null&&vm.OpportunityId==null)ModelState.AddModelError("","Select at least one related CRM record.");if(!ModelState.IsValid)return View(vm);var f=new FollowUp{CustomerId=vm.CustomerId,LeadId=vm.LeadId,OpportunityId=vm.OpportunityId,FollowUpDate=vm.FollowUpDate,FollowUpType=vm.FollowUpType,Subject=vm.Subject,Remarks=vm.Remarks,AssignedToId=Priv&&vm.AssignedToId!=null?vm.AssignedToId:U};db.FollowUps.Add(f);await db.SaveChangesAsync();await audit.LogAsync("CREATE","FollowUp",f.Id.ToString(),null,f.Subject,U);return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Complete(int id,FollowUpStatus status){var f=await db.FollowUps.FindAsync(id);if(f==null)return NotFound();if(!Priv&&f.AssignedToId!=U)return Forbid();f.Status=status;await db.SaveChangesAsync();await audit.LogAsync("STATUS_CHANGE","FollowUp",id.ToString(),null,status.ToString(),U);return RedirectToAction(nameof(Index));}
}
